def table(columns, rows):
    def cell(s): return str(s).replace('|','\\|').replace('\n','<br>')
    return '\n'.join(['| '+' | '.join(columns)+' |','| '+' | '.join(':--' for _ in columns)+' |']+['| '+' | '.join(cell(r[c]) for c in columns)+' |' for r in rows])+'\n'

